// Dedup: Kommo dispara el webhook varias veces por mensaje. Ignora repetidos.
const item = $input.first();
const body = (item.json && item.json.body) ? item.json.body : {};
const id = body['message[add][0][id]'];
const key = id || ((body['message[add][0][element_id]'] || '') + '_' + (body['message[add][0][text]'] || '') + '_' + (body['message[add][0][created_at]'] || ''));
const store = $getWorkflowStaticData('global');
if (!store.seen) store.seen = [];
if (key && store.seen.indexOf(key) !== -1) { return []; }
if (key) { store.seen.push(key); if (store.seen.length > 300) { store.seen = store.seen.slice(-300); } }
return $input.all();

const j = $json;
const raw = (j && j.data && typeof j.data === 'string') ? JSON.parse(j.data) : j;
const statusId = Number(raw.status_id) || 0;
const emb = raw._embedded || {};
const tags = (emb.tags || []).map(t => ({ id: t.id }));
const cfs = (raw && raw.custom_fields_values) || [];
const fb = cfs.find(c => Number(c.field_id) === 2084715);
const bufferRaw = (fb && fb.values && fb.values[0]) ? fb.values[0].value : '';
let buffer = { msgs: [], ts: 0 };
try { if (bufferRaw) buffer = JSON.parse(bufferRaw); } catch (e) {}
if (!Array.isArray(buffer.msgs)) buffer.msgs = [];
// El contacto se usa para buscar el telefono en la lista de silenciados.
const contactId = ((emb.contacts || [])[0] || {}).id || 0;
return [{ json: { statusId: statusId, leadId: $('Edit Fields1').first().json.leadId, tags: tags, bufferMsgs: buffer.msgs, contactId: contactId } }];

const items = $input.all();
const SAFE = 'Disculpá, tuve un inconveniente para procesar tu consulta. Un asesor te va a responder a la brevedad. Te esperamos en Mendoza 758.';
const noEmoji = (s) => (s || '').toString().replace(/[\u{10000}-\u{10FFFF}️]/gu, '');

return items.map((item) => {
  let raw = item.json.output || item.json.text || item.json.response || item.json.message || "";
  raw = (typeof raw === "string") ? raw : JSON.stringify(raw);
  raw = raw.replace(/```json/gi, "").replace(/```/g, "").trim();

  // aislar el objeto JSON: del primer { al ultimo }
  const a = raw.indexOf('{');
  const b = raw.lastIndexOf('}');
  const jsonStr = (a !== -1 && b !== -1 && b > a) ? raw.slice(a, b + 1) : raw;

  let parsed = null;
  try {
    parsed = JSON.parse(jsonStr);
  } catch (e) {
    // ultimo recurso: sacar solo el valor de "respuesta" con regex
    const m = raw.match(/"respuesta"\s*:\s*"((?:[^"\\]|\\.)*)"/);
    let r = SAFE;
    if (m && m[1]) {
      try { r = JSON.parse('"' + m[1] + '"'); } catch (e2) { r = m[1].replace(/\\n/g, '\n').replace(/\\"/g, '"'); }
    }
    // si no pudimos, mandamos mensaje seguro y derivamos a humano. NUNCA el JSON crudo.
    parsed = { respuesta: r, derivar: (r === SAFE), notificar_agustin: false, motivo: 'parse-fallback' };
  }

  const derivar = parsed.derivar === true;
  const notificarAgustin = parsed.notificar_agustin === true;
  let respuesta = noEmoji(parsed.respuesta).trim();
  if (!respuesta) { respuesta = SAFE; }           // nunca vacio
  respuesta = respuesta.substring(0, 1900);

  return { json: {
    respuesta: respuesta,
    derivar: derivar,
    notificarAgustin: notificarAgustin,
    motivo: parsed.motivo || "",
    statusId: 108221247,
    leadId: $('Edit Fields1').first().json.leadId,
  }};
});

