// IMPORTANTE: se limpian emojis (el campo bot_buffer de Kommo trunca en el primer emoji astral
// -> JSON corrupto -> el bot se traba).
const noEmoji = (s) => (s || '').toString().replace(/[\u{10000}-\u{10FFFF}\uFE0F]/gu, '');
const prev = ($('Estado lead').first().json.bufferMsgs || []).map(noEmoji);
const nuevo = noEmoji($('Edit Fields1').first().json.text || '');
const msgs = prev.concat([nuevo]);
const stamp = Date.now();
return [{ json: { leadId: $('Edit Fields1').first().json.leadId, stamp: stamp, bufferJson: JSON.stringify({ msgs: msgs, ts: stamp }) } }];

const raw = ($json && $json.data && typeof $json.data === 'string') ? JSON.parse($json.data) : ($json || {});
const cfs = (raw && raw.custom_fields_values) || [];
const fb = cfs.find(c => Number(c.field_id) === 2084715);
const bufferRaw = (fb && fb.values && fb.values[0]) ? fb.values[0].value : '';
let buffer = { msgs: [], ts: 0 };
try { if (bufferRaw) buffer = JSON.parse(bufferRaw); } catch (e) {}
const miStamp = $('Preparar buffer').first().json.stamp;
if (Number(buffer.ts) !== Number(miStamp)) { return []; }
const texto = (buffer.msgs || []).join('\n');
return [{ json: { leadId: $('Preparar buffer').first().json.leadId, textoJunto: texto } }];

// Saca los ultimos 10 digitos del telefono del contacto, que es la clave con la que
// se compara contra la lista. Se usan los ultimos 10 y no el numero entero porque en
// Kommo el mismo telefono convive en tres formatos y ninguna persona tipea el +549.
//
// Si "Traer contacto" fallo, esto NO rompe: sigue sin telefono y el bot contesta como
// siempre. La pausa es una mejora, no puede ser un motivo para dejar mudo al bot.
let ultimos10 = '';
try {
  const j = $json;
  const raw = (j && j.data && typeof j.data === 'string') ? JSON.parse(j.data) : j;
  const cfs = (raw && raw.custom_fields_values) || [];
  const tel = cfs.find(c => c.field_code === 'PHONE' || Number(c.field_id) === 326778);
  const val = (tel && tel.values && tel.values[0]) ? String(tel.values[0].value || '') : '';
  ultimos10 = val.replace(/\D/g, '').slice(-10);
} catch (e) {}
const est = $('Estado lead').first().json;
return [{ json: { ultimos10: ultimos10, leadId: est.leadId, contactId: est.contactId } }];
